// Hebrew (RTL) seminar paper, fourth revision after the author's comments.
const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, ImageRun,
  Table, TableRow, TableCell, WidthType, ShadingType, LevelFormat, PageBreak,
  Footer, PageNumber, FootnoteReferenceRun
} = require("docx");

const NET = "../networks/";
const FONT = "David";
const SZ = 24;        // 12pt
const LINE = 360;     // 1.5

const T = (t,o={}) => new TextRun({text:t, rightToLeft:true, font:FONT, size:SZ, ...o});
const B = (t,o={}) => T(t,{bold:true, ...o});
const I = (t,o={}) => T(t,{italics:true, ...o});
const L = (t,o={}) => new TextRun({text:t, rightToLeft:false, font:"Cambria", size:SZ-2, ...o});
const M = (t,o={}) => new TextRun({text:t, rightToLeft:false, font:"Consolas", size:SZ-5, ...o});
const FN = n => new FootnoteReferenceRun(n);

const P = (c,o={}) => new Paragraph({
  children:Array.isArray(c)?c:[T(c)], bidirectional:true,
  alignment:AlignmentType.JUSTIFIED, spacing:{after:110,line:LINE}, ...o});
const H1 = t => new Paragraph({
  children:[T(t,{bold:true,size:30,color:"1F3864"})], bidirectional:true,
  alignment:AlignmentType.RIGHT, spacing:{before:280,after:130}, outlineLevel:0});

const img = (file,w,h,caption) => [
  new Paragraph({children:[new ImageRun({type:"png", data:fs.readFileSync(NET+file),
    transformation:{width:w,height:h}})], alignment:AlignmentType.CENTER, spacing:{before:120,after:50}}),
  new Paragraph({children:caption, bidirectional:true, alignment:AlignmentType.CENTER, spacing:{after:150}})
];
const bigImg = (file,caption) => [
  new Paragraph({children:[new PageBreak()]}),
  new Paragraph({children:[new ImageRun({type:"png", data:fs.readFileSync(NET+file),
    transformation:{width:620, height:431}})], alignment:AlignmentType.CENTER, spacing:{before:700,after:60}}),
  new Paragraph({children:caption, bidirectional:true, alignment:AlignmentType.CENTER, spacing:{after:120}}),
  new Paragraph({children:[new PageBreak()]}),
];

function tbl(headers, rows, widths){
  const total = widths.reduce((a,b)=>a+b,0);
  const cell = (c,i,bold) => new TableCell({
    width:{size:widths[i],type:WidthType.DXA},
    shading: bold?{type:ShadingType.CLEAR, fill:"E8EEF7"}:undefined,
    margins:{top:40,bottom:40,left:90,right:90},
    children:[new Paragraph({bidirectional:true, alignment:AlignmentType.RIGHT, spacing:{after:24},
      children:[typeof c==="string" ? (bold?B(c,{size:20}):T(c,{size:20})) : c]})]});
  return new Table({columnWidths:widths, width:{size:total,type:WidthType.DXA}, visuallyRightToLeft:true,
    rows:[ new TableRow({tableHeader:true, cantSplit:true, children:headers.map((h,i)=>cell(h,i,true))}),
      ...rows.map(r=>new TableRow({cantSplit:true, children:r.map((c,i)=>cell(c,i,false))}))]});
}
const CAP = t => new Paragraph({children:[T(t,{size:20,italics:true})], bidirectional:true,
  alignment:AlignmentType.CENTER, spacing:{before:50,after:180}});

const numbering = {config:[
  {reference:"b", levels:[{level:0, format:LevelFormat.BULLET, text:"•", alignment:AlignmentType.RIGHT,
    style:{paragraph:{indent:{right:460,hanging:230}}}}]},
  {reference:"n", levels:[{level:0, format:LevelFormat.DECIMAL, text:"%1.", alignment:AlignmentType.RIGHT,
    style:{paragraph:{indent:{right:460,hanging:280}}}}]}]};
const BUL = c => new Paragraph({children:Array.isArray(c)?c:[T(c)], bidirectional:true,
  numbering:{reference:"b",level:0}, alignment:AlignmentType.JUSTIFIED, spacing:{after:70,line:LINE}});
const NUM = c => new Paragraph({children:Array.isArray(c)?c:[T(c)], bidirectional:true,
  numbering:{reference:"n",level:0}, alignment:AlignmentType.JUSTIFIED, spacing:{after:70,line:LINE}});
const REF = c => new Paragraph({children:Array.isArray(c)?c:[c], bidirectional:false,
  alignment:AlignmentType.LEFT, spacing:{after:60}, indent:{left:420,hanging:420}});
const CODE = t => new Paragraph({children:[M(t)], bidirectional:false, alignment:AlignmentType.LEFT,
  spacing:{after:16}, indent:{left:300}, shading:{type:ShadingType.CLEAR, fill:"F4F4F4"}});

const fnp = c => new Paragraph({bidirectional:true, alignment:AlignmentType.RIGHT, children:c});
